package school.magiccodex.client;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
class HudLayoutStoreTest{
 @TempDir Path dir;
 @Test void defaultPreservesLegacyBaseAndLockNeverIncludesChat(){var s=new HudLayoutStore();var base=new HudLayoutStore.Box(100,80,320,120);assertTrue(s.locked());assertEquals(base,s.fit("hotbar",base,1920,1080));assertNull(s.value("chat"));}
 @Test void normalizedPositionSurvivesResolutionAndSizeChanges(){var s=new HudLayoutStore();var b=new HudLayoutStore.Box(30,20,300,100);s.place("hotbar",b,1920,1080,1500,800,1.2f);var large=s.fit("hotbar",b,1920,1080);assertEquals(1500,large.x(),.1);var small=s.fit("hotbar",b,640,360);assertTrue(small.x()>=0&&small.y()>=0&&small.x()+small.width()<=640.1&&small.y()+small.height()<=360.1);assertEquals(small.x()/(640-small.width()),large.x()/(1920-large.width()),.001);}
 @Test void clampsOversizeOffscreenAndInvalidNumbers(){var s=new HudLayoutStore();var b=new HudLayoutStore.Box(0,0,1500,900);s.place("menu",b,320,200,99999,-99999,Float.POSITIVE_INFINITY);var fit=s.fit("menu",b,320,200);assertTrue(fit.x()>=0&&fit.y()>=0&&fit.width()<=320.1&&fit.height()<=200.1);assertThrows(IllegalArgumentException.class,()->s.place("../bad",b,320,200,0,0,1));}
 @Test void atomicPersistenceAndResetArePerHud()throws Exception{var f=dir.resolve("layouts.properties");var s=new HudLayoutStore();var b=new HudLayoutStore.Box(10,10,100,50);s.locked(false);s.place("menu",b,1000,600,400,250,1.5f);s.place("quest",b,1000,600,100,50,.8f);assertTrue(s.save(f));var reload=HudLayoutStore.load(f);assertFalse(reload.locked());assertEquals(s.value("menu"),reload.value("menu"));reload.reset("menu");assertNull(reload.value("menu"));assertNotNull(reload.value("quest"));reload.reset();assertNull(reload.value("quest"));}
 @Test void corruptCoordinatesCannotEscapeScreen()throws Exception{var f=dir.resolve("layouts.properties");Files.writeString(f,"locked=false\nmenu.x=NaN\nmenu.y=1\nmenu.scale=2\nquest.x=9\nquest.y=-3\nquest.scale=999\n");var s=HudLayoutStore.load(f);assertNull(s.value("menu"));assertEquals(new HudLayoutStore.Placement(1,0,2.5f),s.value("quest"));}
}
